/**
 * Cloudflare Worker entry: OpenNext's Next.js handler plus a Cron Trigger
 * (see wrangler.jsonc) that sends scheduled certificate emails.
 */
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore -- generated by `opennextjs-cloudflare build`; absent before the first build
import { default as handler } from "./.open-next/worker.js";

type Env = { CRON_SECRET?: string; APP_URL?: string };

const worker = {
  fetch: handler.fetch,

  async scheduled(_event: unknown, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
    const base = env.APP_URL ?? "https://givetonne.internal";
    const req = new Request(`${base}/api/cron/deliver`, {
      headers: env.CRON_SECRET ? { authorization: `Bearer ${env.CRON_SECRET}` } : {},
    });
    ctx.waitUntil(
      handler.fetch(req, env, ctx).then(async (res: Response) => {
        console.log(`cron deliver: ${res.status} ${await res.text()}`);
      }),
    );
  },
};

export default worker;

// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore -- generated by `opennextjs-cloudflare build`; absent before the first build
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
